cd /tmp/pcg-eval-VtMsX7/project && node -e '
import("pcg-ts/primitives").then(async () => {
  const { deserializeGraph, cook, firstGeometry } = await import("pcg-ts");
  const fs = await import("node:fs");
  const json = JSON.parse(fs.readFileSync("graph.json", "utf8"));

  async function hashOutputs(seed, outputsOrder) {
    const g = JSON.parse(JSON.stringify(json));
    g.seed = seed;
    const graph = deserializeGraph(g);
    const r1 = await cook(graph, { outputs: outputsOrder });
    const terrain = firstGeometry(r1.outputs.terrain);
    const P = terrain.attrs.point.require("P").data;
    let sum = 0;
    for (let i=0;i<P.length;i++) sum += P[i]*(i+1);
    const trees = r1.outputs.trees[0];
    let tsum = 0, tcount=0;
    for (const b of trees.batches) { tcount += b.transforms.length/16; for (let i=0;i<b.transforms.length;i++) tsum += b.transforms[i]*(i+1); }
    return { sum, tsum, tcount };
  }

  console.log("together", await hashOutputs(1, ["terrain","trees"]));
  console.log("reversed", await hashOutputs(1, ["trees","terrain"]));

  // split cook: cook terrain only then trees only on same graph instance
  const g2 = JSON.parse(JSON.stringify(json)); g2.seed = 1;
  const graph2 = deserializeGraph(g2);
  const rA = await cook(graph2, { outputs: ["terrain"] });
  const rB = await cook(graph2, { outputs: ["trees"] });
  const terrainA = firstGeometry(rA.outputs.terrain);
  const PA = terrainA.attrs.point.require("P").data;
  let sumA=0; for (let i=0;i<PA.length;i++) sumA += PA[i]*(i+1);
  let tsumB=0, tcountB=0;
  for (const b of rB.outputs.trees[0].batches) { tcountB += b.transforms.length/16; for (let i=0;i<b.transforms.length;i++) tsumB += b.transforms[i]*(i+1); }
  console.log("split", { sumA, tsumB, tcountB });
});
' 2>&1

