cat > /tmp/split_check.mjs << 'EOF'
import { deserializeGraph, cook, firstGeometry } from "pcg-ts";
import fs from "node:fs";
const raw = JSON.parse(fs.readFileSync("./graph.json", "utf8"));
const graph = deserializeGraph(raw);

const full = await cook(graph);
const g2 = deserializeGraph(raw);
const terrainOnly = await cook(g2, { outputs: ["terrain"] });
const treesOnly = await cook(g2, { outputs: ["trees"] });

const P1 = firstGeometry(full.outputs.terrain).attrs.point.require("P").data;
const P2 = firstGeometry(terrainOnly.outputs.terrain).attrs.point.require("P").data;
console.log("terrain P identical across split cook:", Buffer.from(P1.buffer).equals(Buffer.from(P2.buffer)));

const b1 = full.outputs.trees.find(i=>i.kind==="instances").batches[0].transforms;
const b2 = treesOnly.outputs.trees.find(i=>i.kind==="instances").batches[0].transforms;
console.log("trees transforms identical across split cook:", Buffer.from(b1.buffer).equals(Buffer.from(b2.buffer)));
EOF
